async function main() {
  console.log('🌱 Starting seed...');

  // Clear existing data
  await prisma.specializationTopic.deleteMany();
  await prisma.material.deleteMany();
  await prisma.topic.deleteMany();
  await prisma.specialization.deleteMany();
  await prisma.examVersion.deleteMany();
  await prisma.user.deleteMany();

  // Create exam version
  const examVersion = await prisma.examVersion.create({
    data: {
      name: 'RD13/2026',
      academicYear: '2025/26',
      isActive: true
    }
  });
  console.log(`Created exam version: ${examVersion.name}`);

  // Create user (admin)
  const hashedPassword = await bcrypt.hash('admin123', 10);
  const user = await prisma.user.create({
    data: {
      username: 'admin',
      password: hashedPassword,
      role: 'admin',
      name: 'Admin'
    }
  });
  console.log(`Created admin user: ${user.username}`);

  // Create specializations and topics
  for (const spec of specializations) {
    console.log(`Creating specialization: ${spec.code} - ${spec.name}`);
    
    const specialization = await prisma.specialization.create({
      data: {
        code: spec.code,
        name: spec.name,
        description: spec.description
      }
    });

    let position = 1;
    for (const topicTitle of spec.topics) {
      // Check if topic already exists
      let topic = await prisma.topic.findFirst({
        where: { title: topicTitle }
      });

      if (!topic) {
        topic = await prisma.topic.create({
          data: {
            title: topicTitle,
            scope: 'SPECIALIZATION'
          }
        });
      }

      // Map topic to specialization
      await prisma.specializationTopic.create({
        data: {
          specializationId: specialization.id,
          topicId: topic.id,
          examVersionId: examVersion.id,
          position: position++
        }
      });
    }

    console.log(`  Created ${spec.topics.length} topics for ${spec.code}`);
  }

  console.log('✅ Seed completed successfully!');
}

main()
  .catch((e) => {
    console.error('❌ Seed failed:', e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
